BEGIN TRANSACTION;
CREATE TABLE collection_scope (scope_id INTEGER PRIMARY KEY,start_date TEXT NOT NULL,end_date TEXT NOT NULL,exclusions TEXT NOT NULL);
CREATE TABLE competitions (competition_id INTEGER PRIMARY KEY,competition_code TEXT UNIQUE NOT NULL,competition_name TEXT NOT NULL,country TEXT NOT NULL);
CREATE TABLE seasons (season_id INTEGER PRIMARY KEY,competition_id INTEGER NOT NULL,season_label TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT);
CREATE TABLE source_registry (source_id INTEGER PRIMARY KEY,source_name TEXT NOT NULL,source_type TEXT NOT NULL,authority_level TEXT NOT NULL,url TEXT,notes TEXT);
CREATE TABLE matches (match_id TEXT PRIMARY KEY,competition_id INTEGER NOT NULL,season_id INTEGER,kickoff TEXT NOT NULL,home_team TEXT NOT NULL,away_team TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'scheduled',source_status TEXT NOT NULL DEFAULT 'pending',primary_source_id INTEGER);
CREATE TABLE results (match_id TEXT PRIMARY KEY,ht_home INTEGER,ht_away INTEGER,ft_home INTEGER,ft_away INTEGER,result_1x2 TEXT,completed_at TEXT,source_status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE sporttery_market (market_id INTEGER PRIMARY KEY AUTOINCREMENT,match_id TEXT NOT NULL,pool_code TEXT NOT NULL,handicap REAL,home_value REAL,draw_value REAL,away_value REAL,captured_at TEXT,source_status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE team_features (match_id TEXT NOT NULL,team_side TEXT NOT NULL,last3 TEXT,last5 TEXT,last10 TEXT,goals_for REAL,goals_against REAL,xg_for REAL,xg_against REAL,opponent_strength REAL,PRIMARY KEY(match_id,team_side));
CREATE TABLE schedule_intent (match_id TEXT NOT NULL,team_side TEXT NOT NULL,next_opponent TEXT,next_match_time TEXT,rest_days REAL,next_match_importance TEXT,rotation_risk REAL,motivation_adjustment REAL,PRIMARY KEY(match_id,team_side));
CREATE TABLE injuries (injury_id INTEGER PRIMARY KEY AUTOINCREMENT,match_id TEXT NOT NULL,team_side TEXT NOT NULL,player TEXT NOT NULL,status TEXT,reason TEXT,expected_return TEXT,source_status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE prediction_snapshot (prediction_id INTEGER PRIMARY KEY AUTOINCREMENT,match_id TEXT NOT NULL,snapshot_time TEXT NOT NULL,data_cutoff TEXT NOT NULL,handicap REAL,handicap_prediction TEXT,score_1 TEXT,score_2 TEXT,half_full TEXT,model_confidence REAL,notes TEXT);
CREATE TABLE review (review_id INTEGER PRIMARY KEY AUTOINCREMENT,match_id TEXT NOT NULL,prediction_id INTEGER,actual_result TEXT,handicap_actual TEXT,hit_status TEXT,error_type TEXT,error_reason TEXT,calibration_change TEXT,reviewed_at TEXT);
COMMIT;
